      role3 = 202201,
      sentence = "His calm acceptance, that quiet look in his eyes—it hit me like a weight to the chest.",
      next = {53}
    },
    [53] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      sentence = "Lucien had probably known for a while now that something was off with me.",
      next = {54}
    },
    [54] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      sentence = "I've never been good at hiding things from him. Somehow, it felt like he already knew the solitary nights that I had to endure—the ones where I'd jolt awake, shaken by dreams of blood and guilt.",
      next = {55}
    },
    [55] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      sentence = "I didn't know how to respond. I should've looked worried. I should've said something comforting. But more than anything, I wanted to tell him the truth—that the so-called \"werewolf\" he feared had never once thought of hurting him.",
      next = {56}
    },
    [56] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      sentence = "And still, I hesitated. Do I bury the truth deeper each night and keep playing in this cruel charade? Or do I lay it all bare right here, right now?",
      next = {57}
    },
    [57] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      sentence = "The weight of a thousand unspoken thoughts locked me in place. I didn't even know what kind of expression I had on, but I knew it didn't look right.",
      next = {58}
    },
    [58] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.1,
      sentence = "His moist fingers brushed across my skin, sending a shiver down my limbs. I looked up to find Lucien standing before me.",
      next = {59}
    },
    [59] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      sentence = "Then, he opened his arms, letting his warm embrace answer the question that I could not find an answer to.",
      next = {60}
    },
    [60] = {
      beijing = 4967,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "18_Sorrow_love",
      renming = "Lucien",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      sentence = "Don't be scared. We'll make it through this. Together.",
      next = {61}
    },
    [61] = {
      beijing = 4967,
      dialog = 3,
      music = "18_Sorrow_love",
      renwu = "npc",
      role1 = 2177000,
      role2 = 202101,
      role3 = 202201,
      roleanim = 1.2,
      ruchang = 9,
      sentence = "Surrounded by the shimmer of water and wavering reflections, I melted into his arm. And that long, wordless hug washed away every unease, every trepidation, and every secret that I could not speak aloud.",
      next = {0}
    }
  },
