  [445065] = {
    [1] = {
      beijing = 3731,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      sentence = "When the army returned victoriously to the capital, it happened to be the winter solstice, the coldest day of the year. But the commoners of the capital all turned out in the streets anyway to welcome home their returning heroes.",
