    [3] = {
      beijing = 3731,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      sentence = "The emperor sat upon the dragon throne, his heavy, drooping crown hiding his face. Gavin went straight up and handed over the enemy's signed surrender.",
      next = {4}
