      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      sentence = "An attendant respectfully presented it to the emperor, who looked it over without a word. All was silent in the great hall. I held a curtseying pose and felt nothing by the cold sweat on my brow.",
      next = {5}
    },
    [5] = {
      beijing = 3731,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      sentence = "This was my second audience with the emperor. The profound authority of that man upon the dragon throne made my heart shrink with fear.",
