    },
    [8] = {
      beijing = 3731,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      sentence = "He said the words calmly, then an attendant holding an imperial edict walked over. Out of the corner of my eye, I could see the black dragon insignia upon it, giving me an incredible shock.",
