      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "His words were filled with rock-solid assurance. My head shot up, and I saw him standing there, his back ram-rod straight, like a pine towering to the sky amidst the shadows.",
