      sentence = "The day before the throne ascension ceremony, the Ministry of Rites sent an inventory for conferring the empress's title, but it was missing a ceremonial dress. Because the announcement of the new emperor and the new empress were happening simultaneously, the Ministry of Rites didn't have time to produce a new dress.",
      next = {45}
    },
    [45] = {
      beijing = 8000,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "Thinking that it was fine to just use a previous one, I picked up a pen to rewrite the list. Just as I was busy writing, a voice suddenly wafted over the table.",
      next = {46}
    },
    [46] = {
      beijing = 8000,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "57_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402205,
      role5 = 4120401,
      ruchang = -1,
      sentence = "What are you writing?",
      voice = 2,
      next = {47}
    },
    [47] = {
      beijing = 8000,
      dhead = 1501,
      dialog = 1,
      music = "57_Tanabata",
      renming = "$u",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402206,
      role5 = 4120401,
      sentence = "An inventory for the Ministry of Rites. I can use a hand-me-down for the empress's dress.",
      next = {48}
    },
    [48] = {
      beijing = 8000,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402206,
      role5 = 4120401,
      ruchang = 9,
      sentence = "Having said that, I could feel this person across from me fall silent. As I looked up in confusion, something ice cold was suddenly held to my chin.",
      next = {49}
    },
    [49] = {
      beijing = 64062,
      bganim = 0,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "The object pushed insistently upward on my chin. On the other end of the sword handle, Gavin was eyeing me with a frown.",
      next = {50}
    },
    [50] = {
      beijing = 64062,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "He stared intently at me and asked pointedly:",
      next = {51}
    },
    [51] = {
      beijing = 64062,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "57_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      sentence = "You don't want a ceremonial dress belonging only to you?",
      voice = 2,
      next = {52}
    },
    [52] = {
      beijing = 64062,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "I found myself thinking back to the Northlands and how I arrived bearing an edict, and he rode past me on horseback, kicking up a cloud of sand.",
      next = {53}
    },
    [53] = {
      beijing = 64062,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "That was a fine day in the Northlands. And a lot like now, he used a horse whip to push up my fur cap.",
      next = {54}
    },
    [54] = {
      beijing = 64062,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "I shook my head with a laugh.",
      next = {55}
    },
    [55] = {
      beijing = 64062,
      dhead = 1507,
      dialog = 1,
      music = "57_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "It's not important. I've already got what I want.",
      next = {56}
    },
    [56] = {
      beijing = 64062,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "57_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      sentence = "But this is a once in a lifetime occasion. I want it to be meaningful.",
      voice = 2,
      next = {57}
    },
    [57] = {
      beijing = 64062,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "He put away the sword handle, and without allowing me to object, he took me by the hand and out of the room.",
      next = {58}
    },
    [58] = {
      beijing = 4496,
      bganim = 0,
