      dialog = 1,
      music = "57_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "Is this... a wedding dress?",
      next = {59}
    },
    [59] = {
      beijing = 4496,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "I stood in the imperial bed chamber of the east palace, beside myself with shock. Before me hung a wedding dress made from all kinds of materials and glimmering with light.",
      next = {60}
    },
    [60] = {
      beijing = 4496,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "I couldn't help reach out and gently feel its exquisite embroidery.",
      next = {61}
    },
    [61] = {
      beijing = 4496,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      sentence = "Golden thread outlined a river sunset and mountain range. The vivid red wedding dress was covered with a rich tapestry of natural beauty.",
      next = {62}
    },
    [62] = {
      beijing = 4496,
      dhead = 1511,
      dialog = 1,
      music = "57_Tanabata",
      renming = "$u",
      renwu = "npc",
      sentence = "Wedding dresses usually have a phoenix embroidered on them, but this one...",
