    },
    [64] = {
      beijing = 4496,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "57_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      sentence = "Back at Grandletter Academy, you always said you wanted to see them. Then, even though you went to the Northlands, you were always too busy and didn't get to see most of the sights.",
      voice = 2,
      next = {65}
    },
    [65] = {
