      idx = 4,
      male = 4,
      music = "57_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      sentence = "In these past three years, I've been all over the map, and I made a drawing of the Northlands as I saw it. Later I found someone to embroider this wedding dress.",
      voice = 2,
      next = {66}
    },
    [66] = {
      beijing = 4496,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      sentence = "He took down the dress and put it on for me himself. By then, the sky was dark, and at some point, the candles had been lit in the East Palace.",
      next = {67}
    },
    [67] = {
      beijing = 4496,
      dialog = 3,
      music = "57_Tanabata",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      sentence = "As Gavin looked at me in the wedding dress, the candlelights shone faintly in his eyes. A moment later, he let out a sudden laugh.",
      next = {68}
    },
    [68] = {
      beijing = 4496,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "57_Tanabata",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      ruchang = 9,
      sentence = "There's somewhere I want to take you.",
      voice = 2,
      next = {69}
    },
    [69] = {
      beijing = 2253,
      bganim = 0,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "The moon lit up the desolate Phoenix Tower. Gavin and I walked shoulder to shoulder up the stairs bathed in moonlight.",
      next = {70}
    },
    [70] = {
      beijing = 2253,
      dialog = 2,
      idx = 4,
