      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      ruchang = -1,
      sentence = "Tomorrow, this is where I plan to hold the ceremony.",
      voice = 2,
      next = {71}
    },
    [71] = {
      beijing = 2253,
      dhead = 1511,
      dialog = 1,
