      renming = "$u",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      sentence = "This is a long way from the imperial palace. Historically, that's where most new emperors choose to do with throne ascension. Why does Your Highness choose here?",
      next = {72}
    },
    [72] = {
      beijing = 2253,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "There was a tranquil, starry brilliance in his eyes as he gently stroked my fingertips, chilled by the evening winds. He softly explained: ",
      next = {73}
    },
    [73] = {
      beijing = 2253,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "28_Double_Seventh02",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "The Phoenix Tower is the most crucial pass outside of the capital. Together with the Jade Gate, they are known as the Two Gates of Yu, the most important lines of defense in the country.",
      voice = 2,
      next = {74}
    },
    [74] = {
