      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "The moon here at Phoenix Tower is the same one you can see at the Jade Gate.",
      voice = 2,
      next = {75}
    },
    [75] = {
