      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "I followed his gaze into the distance, seeing the never-ending land stretch onward under the brilliant moonlight.",
      next = {76}
    },
    [76] = {
