      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "Suddenly, everything was clear to me. I weaved my fingers tightly between his.",
      next = {77}
    },
    [77] = {
      beijing = 2253,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "28_Double_Seventh02",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "I pledge to all the soldiers who were buried at the Jade Gate that I won't be an emperor who lives in luxury in the capital.",
      voice = 2,
      next = {78}
    },
    [78] = {
      beijing = 2253,
