      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120107,
      role3 = 402206,
      role5 = 4120401,
      sentence = "I will guard over this land they gave their lives for. That's the first reason.",
      voice = 2,
      next = {79}
    },
    [79] = {
