      music = "28_Double_Seventh02",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402206,
      role5 = 4120401,
      sentence = "He looked at me with an ease on his face and a glow in his eye like the winter stars.",
      next = {81}
    },
    [81] = {
