      renming = "Gavin",
      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402206,
      role5 = 4120401,
      sentence = "During the Battle of Jade Gate, I almost didn't recover from those injuries. The only reason I was able to wake up was because I had made you a promise.",
      voice = 2,
      next = {82}
    },
    [82] = {
