      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402202,
      role5 = 4120401,
      sentence = "Just clinging to that thought, time after time I found a way to survive on the battlefield.",
      voice = 2,
      next = {86}
    },
    [86] = {
