      renwu = "npc",
      role1 = 4120000,
      role2 = 4120108,
      role3 = 402206,
      role5 = 4120401,
      sentence = "The night wind blew by, carrying his scent with it. With my eyes fixed on him, all I could feel was as if something had filled my heart to bursting.",
