      role1 = 4120000,
      role2 = 4120108,
      role3 = 402206,
      role5 = 4120401,
      sentence = "Ever since my youth, there was only one person I ever loved. I wanted to be with him, to protect him, to shield him from the wind and sand of the frontiers, and the speeches of the royal court.",
